ranges.text:
    tabs::TabHandle active_tab_handle) {
  tabs::TabInterface* active_tab = active_tab_handle.Get();
  if (!active_tab || !window_ ||
      tab_strip_model_->GetActiveTab() != active_tab) {
    return;
  }
  BrowserFocusController::From(this)->FocusWebContentsPane();
}

void Browser::OnTabDeactivated(WebContents* contents) {
  ExclusiveAccessManager::From(this)->OnTabDeactivated(contents);
  SearchTabHelper::FromWebContents(contents)->OnTabDeactivated();

  // Save what the user's currently typing, so it can be restored when we
  // switch back to this tab.
  window_->GetLocationBar()->SaveStateToContents(contents);
}

void Browser::OnActiveTabChanged(const TabStripModelChange& change,
                                 const TabStripSelectionChange& selection) {
  TRACE_EVENT0("ui", "Browser::OnActiveTabChanged");

  // The side panel state needs to be updated on active tab changed
  // even if the tab strip is empty.
  if (change.type() != TabStripModelChange::kReplaced &&
      !tab_strip_model_->closing_all()) {
    SidePanelUI* side_panel_ui = SidePanelUI::From(this);
    if (side_panel_ui) {
      side_panel_ui->OnActiveTabChanged(
          selection.old_contents, selection.new_contents,
          /*tab_removed_for_deletion=*/
          (change.type() == TabStripModelChange::kRemoved) &&
              (TabRemoveReasonUtils::WillDeleteTab(
                  change.GetRemove()->contents[0].remove_reason)));
    }
  }

  if (tab_strip_model_->empty()) {
    return;
  }

// Mac correctly sets the initial background color of new tabs to the theme
// background color, so it does not need this block of code. Aura should
// implement this as well.
// https://crbug.com/41317454

}

void Browser::TabDetachedAtImpl(content::WebContents* contents,
                                bool was_active,
                                DetachType type) {
  if (type == DetachType::kDetach) {
    // Save the current location bar state, but only if the tab being detached
    // is the selected tab.  Because saving state can conditionally revert the
    // location bar, saving the current tab's location bar state to a
    // non-selected tab can corrupt both tabs.
    if (was_active) {
      LocationBar* location_bar = window_->GetLocationBar();
      if (location_bar) {
        location_bar->SaveStateToContents(contents);
      }
    }
  }

  SetAsDelegate(contents, false);
  BrowserUiController::From(this)->RemoveScheduledUpdatesFor(contents);

void OmniboxViewViews::SaveStateToTab(content::WebContents* tab) {
  DCHECK(tab);

  // We don't want to keep the IME status, so force quit the current
  // session here.  It may affect the selection status, so order is
  // also important.
  if (IsIMEComposing()) {
    ConfirmCompositionText(/* keep_selection */ false);
    GetInputMethod()->CancelComposition(this);
  }

  // NOTE: GetStateForTabSwitch() may affect GetSelectedRange(), so order is
  // important.
  const OmniboxEditModel::State state =
      controller()->edit_model()->GetStateForTabSwitch();
  tab->SetUserData(
      OmniboxTabHelper::kOmniboxStateKey,
      std::make_unique<OmniboxState>(state, GetSelectedRange(),
                                     saved_selection_for_focus_change_));
  UpdateAccessibleTextSelection();
}

void OmniboxViewViews::OnTabChanged(content::WebContents* web_contents) {
  // Observe the WebContents for title changes and navigations for updating the
  // placeholder text.
  Observe(web_contents);

  if (!base::FeatureList::IsEnabled(omnibox::kWebUIOmniboxFullPopup)) {
    const OmniboxState* state = static_cast<OmniboxState*>(
        web_contents->GetUserData(OmniboxTabHelper::kOmniboxStateKey));
    controller()->edit_model()->RestoreState(state ? &state->model_state
                                                   : nullptr);
    if (state) {
      // This assumes that the omnibox has already been focused or blurred as
      // appropriate; otherwise, a subsequent OnFocus() or OnBlur() call could
      // goof up the selection.  See comments on OnActiveTabChanged() call in
      // Browser::ActiveTabChanged().
      if (state->model_state.user_input_in_progress &&
          state->model_state.user_text.empty() &&
          state->model_state.keyword.empty()) {
        // See comment in OmniboxEditModel::GetStateForTabSwitch() for details
        // on this.
        SelectAll(true);
        saved_selection_for_focus_change_ = gfx::Range();
      } else {
        SetSelectedRange(state->selection);
        saved_selection_for_focus_change_ =
            state->saved_selection_for_focus_change;
      }
    }
  }

  // TODO(msw|oshima): Consider saving/restoring edit history.
  ClearEditHistory();

}

